 43→
 44→// ─── Plan data ────────────────────────────────────────────────────────────────
 45→
 46→const PLANS_DATA = {
 47→  free: {
 48→    id: "free",
 49→    name: "Free",
 50→    monthlyPrice: 0,
 51→    annualPrice: 0,
