 62→    shopifyPlanAnnual: null as string | null,
 63→  },
 64→  starter: {
 65→    id: "starter",
 66→    name: "Starter",
 67→    monthlyPrice: 4.99,
 68→    annualPrice: 39,
 69→    annualMonthlyPrice: 3.25,
 70→    description: "Essential features for small stores",
 71→    features: [
