 94→      "Unlimited delivery rules",
 95→      "Full customer waitlist",
 96→      "Bulk CSV import & export",
 97→      "Cart & checkout blocking",
 98→      "Priority email support",
 99→    ],
100→    shopifyPlanMonthly: PLAN_PRO_MONTHLY,
101→    shopifyPlanAnnual: PLAN_PRO_ANNUAL,
102→    bestValue: true,
103→  },
104→  ultimate: {
105→    id: "ultimate",
106→    name: "Ultimate",
107→    monthlyPrice: 19.99,
108→    annualPrice: 149,
109→    annualMonthlyPrice: 12.42,
110→    description: "Enterprise-grade power and flexibility",
111→    features: [
112→      "Everything in Pro",
113→      "Custom widget CSS",
114→      "API access",
115→      "24/7 VIP support",
116→      "Early access to new features",
117→    ],
118→    shopifyPlanMonthly: PLAN_ULTIMATE_MONTHLY,
119→    shopifyPlanAnnual: PLAN_ULTIMATE_ANNUAL,
120→  },
121→};
122→
123→// ─── Loader ───────────────────────────────────────────────────────────────────
124→
125→export const loader = async ({ request }: LoaderFunctionArgs) => {
126→  const { session, billing } = await authenticate.admin(request);
127→  const shop = session.shop;
128→
129→  try {
130→    /* eslint-disable @typescript-eslint/no-explicit-any */
131→    const billingCheck = await billing.check({
132→      plans: ALL_PAID_PLANS as any,
133→      isTest: process.env.NODE_ENV !== "production",
134→    });
135→    /* eslint-enable @typescript-eslint/no-explicit-any */
136→    const subscription = await syncSubscriptionFromShopify(
137→      shop,
138→      billingCheck.appSubscriptions ?? [],
139→    );
140→    return { subscription };
141→  } catch {
142→    const subscription = await getShopSubscription(shop);
143→    return { subscription };
144→  }
145→};
146→
147→// ─── Action ───────────────────────────────────────────────────────────────────
148→
149→export const action = async ({ request }: ActionFunctionArgs): Promise<
150→  | { confirmationUrl: string }
151→  | { error: string }
152→  | { success: boolean; message: string }
153→  | null
154→> => {
155→  const { session, billing } = await authenticate.admin(request);
156→  const shop = session.shop;
157→  const formData = await request.formData();
158→  const intent = String(formData.get("intent"));
159→
160→  if (intent === "subscribe") {
161→    const plan = String(formData.get("plan"));
162→    const returnUrl = `${process.env.SHOPIFY_APP_URL}/app/pricing`;
163→    try {
164→      /* eslint-disable @typescript-eslint/no-explicit-any */
165→      const confirmationUrl = await billing.request({
166→        plan: plan as any,
167→        isTest: process.env.NODE_ENV !== "production",
168→        returnUrl,
169→      }) as string;
170→      /* eslint-enable @typescript-eslint/no-explicit-any */
171→      return { confirmationUrl };
172→    } catch {
173→      return { error: "Failed to initiate subscription. Please try again." };
174→    }
175→  }
176→
177→  if (intent === "cancel") {
178→    try {
179→      const sub = await getShopSubscription(shop);
180→      if (sub.shopifySubscriptionId) {
181→        await billing.cancel({
182→          subscriptionId: sub.shopifySubscriptionId,
183→          isTest: process.env.NODE_ENV !== "production",
184→          prorate: true,
185→        });
186→      }
187→      await cancelShopSubscription(shop);
188→      return {
189→        success: true,
190→        message: "Subscription cancelled. You are now on the Free plan.",
191→      };
192→    } catch {
193→      return { error: "Failed to cancel subscription. Please try again." };
194→    }
195→  }
196→
197→  return null;
198→};
199→
200→// ─── Feature row ─────────────────────────────────────────────────────────────
201→
202→function PlanFeature({ feature }: { feature: string }) {
203→  return (
204→    <InlineStack gap="200" blockAlign="start" wrap={false}>
205→      <Box>
206→        <Icon source={CheckCircleIcon} tone="success" />
207→      </Box>
208→      <Text as="span" variant="bodyMd">
209→        {feature}
210→      </Text>
211→    </InlineStack>
212→  );
213→}
214→
215→// ─── Plan card ────────────────────────────────────────────────────────────────
216→
217→type PlanCardProps = {
218→  plan: (typeof PLANS_DATA)[keyof typeof PLANS_DATA];
219→  isAnnual: boolean;
220→  currentTier: string;
221→  onSubscribe: (planName: string) => void;
222→  onRequestCancel: () => void;
223→  loadingPlan: string | null;
224→};
225→
226→function PlanCard({
227→  plan,
228→  isAnnual,
229→  currentTier,
230→  onSubscribe,
231→  onRequestCancel,
232→  loadingPlan,
233→}: PlanCardProps) {
234→  const isCurrent = currentTier === plan.id;
235→  const isBestValue = "bestValue" in plan && plan.bestValue;
236→  const isCurrentPaid = currentTier !== "free";
237→  const isDowngradeToFree = plan.id === "free" && isCurrentPaid;
238→
239→  const TIER_ORDER: Record<string, number> = {
240→    free: 0,
241→    starter: 1,
242→    pro: 2,
243→    ultimate: 3,
244→  };
245→  const isUpgrade =
246→    !isCurrent &&
247→    plan.id !== "free" &&
248→    (TIER_ORDER[plan.id] ?? 0) > (TIER_ORDER[currentTier] ?? 0);
249→
250→  const shopifyPlan = isAnnual
251→    ? plan.shopifyPlanAnnual
252→    : plan.shopifyPlanMonthly;
253→
254→  const displayPrice = isAnnual ? plan.annualMonthlyPrice : plan.monthlyPrice;
255→
256→  let buttonContent = "Start 7-day free trial";
257→  if (isCurrent) {
258→    buttonContent = "Current plan";
259→  } else if (isDowngradeToFree) {
260→    buttonContent = "Downgrade to Free";
261→  } else if (isUpgrade) {
262→    buttonContent = `Upgrade to ${plan.name}`;
263→  } else if (!isCurrent && plan.id !== "free" && isCurrentPaid) {
264→    buttonContent = `Switch to ${plan.name}`;
265→  }
266→
267→  const handleClick = () => {
268→    if (isCurrent) return;
269→    if (isDowngradeToFree) {
270→      onRequestCancel();
271→    } else if (shopifyPlan) {
272→      onSubscribe(shopifyPlan);
273→    }
274→  };
275→
276→  const isThisLoading = loadingPlan === (shopifyPlan ?? "cancel");
277→
278→  return (
279→    <Card>
280→      <BlockStack gap="400">
281→
282→        {/* Plan name + badges */}
