/**
 * GDPR: customers/data_request
 *
 * Shopify sends this when a customer requests a copy of their data.
 * You must respond within 30 days by sending the data to the customer.
 *
 * Required for Shopify App Store listing.
 * https://shopify.dev/docs/apps/build/privacy-law-compliance
 */
import type { ActionFunctionArgs } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";

export const action = async ({ request }: ActionFunctionArgs) => {
  const { shop, payload, topic } = await authenticate.webhook(request);

  console.log(`Received ${topic} webhook for ${shop}`);

  const customerId = payload?.customer?.id;
  const customerEmail = payload?.customer?.email;

  // Log the data request for manual fulfilment or integrate with your
  // data export system. Shopify does not auto-send the data — you must
  // respond to the customer directly within 30 days.
  console.log(
    `Data request for customer ${customerId} (${customerEmail}) on shop ${shop}`,
  );

  // Example: look up waitlist entries for this customer's email
  if (customerEmail) {
    const waitlistEntries = await db.waitlistEntry.findMany({
      where: { shop, email: customerEmail },
      select: { zipCode: true, status: true, createdAt: true },
    });
    console.log(
      `Found ${waitlistEntries.length} waitlist entries for ${customerEmail}`,
    );
  }

  return new Response();
};

