                            borderRadius="full"
                            padding="100"
                            minWidth="24px"
                            minHeight="24px"
                          >
                            <Text
                              as="span"
                              variant="bodySm"
                              fontWeight="bold"
                              alignment="center"
                              tone="text-inverse"
                            >
                              {item.step}
                            </Text>
                          </Box>
                          <Text as="h3" variant="headingSm">
