import type { ActionFunctionArgs } from "react-router";
import { authenticate } from "../shopify.server";
import { syncSubscriptionFromShopify } from "../billing.server";

export const action = async ({ request }: ActionFunctionArgs) => {
  const { shop, payload } = await authenticate.webhook(request);

  console.log(`Received app_subscriptions/update webhook for ${shop}`);

  try {
    type SubscriptionPayload = {
      app_subscription?: {
        admin_graphql_api_id?: string;
        name?: string;
        status?: string;
      };
    };

    const data = payload as SubscriptionPayload;
    const sub = data?.app_subscription;

    if (sub) {
      await syncSubscriptionFromShopify(shop, [
        {
          id: sub.admin_graphql_api_id ?? "",
          name: sub.name ?? "",
          status: sub.status ?? "",
        },
      ]);
      console.log(`Synced subscription for ${shop}: ${sub.name} → ${sub.status}`);
    }
  } catch (err) {
    console.error(`Failed to sync subscription for ${shop}:`, err);
  }

  return new Response();
};

/**
 * GDPR: shop/redact
 *
 * Shopify sends this 48 hours after a merchant uninstalls the app.
 * You must delete all data stored for this shop.
 *
 * Required for Shopify App Store listing.
 * https://shopify.dev/docs/apps/build/privacy-law-compliance
 */
import type { ActionFunctionArgs } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";

export const action = async ({ request }: ActionFunctionArgs) => {
  const { shop, topic } = await authenticate.webhook(request);

  console.log(`Received ${topic} webhook for ${shop} — deleting all shop data`);

  // Delete all shop data in parallel
  await Promise.all([
    db.zipCode.deleteMany({ where: { shop } }),
    db.deliveryRule.deleteMany({ where: { shop } }),
    db.waitlistEntry.deleteMany({ where: { shop } }),
    db.widgetConfig.deleteMany({ where: { shop } }),
    db.subscription.deleteMany({ where: { shop } }),
    db.session.deleteMany({ where: { shop } }),
    db.shopSettings.deleteMany({ where: { shop } }), // contains notificationEmail (PII)
  ]);

  console.log(`All data deleted for shop ${shop}`);

  return new Response();
};

